function formatStorageSize(bytes){if(!Number.isFinite(bytes)||bytes<0)return '—';const units=['Б','КиБ','МиБ','ГиБ'];let value=bytes,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return `${new Intl.NumberFormat('ru-RU',{maximumFractionDigits:index?1:0}).format(value)} ${units[index]}`}
async function refreshStorageStatus(){
  const panel=$('#storage-reliability');
  if(!panel)return;
  const title=$('#storage-persistence-title'),description=$('#storage-persistence-description'),usageLabel=$('#storage-usage'),meter=$('#storage-meter'),fill=$('#storage-meter-fill'),requestButton=$('[data-action="request-persistent-storage"]');
  panel.dataset.storageStatus='checking';
  title.textContent='Проверяем хранилище…';
  description.textContent='Оцениваем место и статус защиты в этом браузере.';
  const report=await inspectBrowserStorage();
  if(!report.supported){
    panel.dataset.storageStatus='unavailable';
    title.textContent='Оценка хранилища недоступна';
    description.textContent='Этот браузер не показывает расход места. Экспорт JSON остаётся доступен.';
    usageLabel.textContent='—';
    meter.hidden=true;
    requestButton.hidden=true;
    return;
  }
  usageLabel.textContent=report.usage===null?'Недоступно':`${formatStorageSize(report.usage)} из ${formatStorageSize(report.quota)}`;
  const canMeasure=report.usage!==null&&report.quota>0;
  if(canMeasure){
    const percentage=Math.max(0,Math.min(100,Math.round(report.usage/report.quota*100)));
    meter.hidden=false;
    meter.setAttribute('aria-valuenow',String(percentage));
    meter.setAttribute('aria-valuetext',`${percentage}% занято`);
    fill.style.width=`${percentage}%`;
  }else meter.hidden=true;
  if(report.persistent===true){
    panel.dataset.storageStatus='protected';
    title.textContent='Защита хранилища включена';
    description.textContent='Браузер не должен автоматически вытеснять эти данные. Всё равно сохраняйте резервную копию.';
    requestButton.textContent='Защита включена';
    requestButton.disabled=true;
    requestButton.hidden=false;
  }else if(report.persistent===false&&report.persistentSupported){
    panel.dataset.storageStatus='best-effort';
    title.textContent='Браузер может очистить данные';
    description.textContent='При нехватке места браузер может удалить локальную копию. Запросите защиту и регулярно сохраняйте JSON.';
    requestButton.textContent='Попросить защиту от автоочистки';
    requestButton.disabled=false;
    requestButton.hidden=false;
  }else if(report.persistentSupported){
    panel.dataset.storageStatus='unknown';
    title.textContent='Не удалось проверить статус защиты';
    description.textContent='Можно запросить защиту ещё раз; отказ браузера не мешает экспорту JSON.';
    requestButton.textContent='Повторить запрос защиты';
    requestButton.disabled=false;
    requestButton.hidden=false;
  }else{
    panel.dataset.storageStatus='unsupported';
    title.textContent='Защита хранилища не поддерживается';
    description.textContent='Данные остаются в этом браузере, но статус автоочистки неизвестен. Сохраняйте JSON-копию вне профиля.';
    requestButton.hidden=true;
  }
}
async function requestStorageProtection(){const button=$('[data-action="request-persistent-storage"]');if(!button)return;button.disabled=true;button.textContent='Запрашиваем…';const result=await requestPersistentBrowserStorage();await refreshStorageStatus();if(!result.supported)toast('Браузер не поддерживает защиту от автоочистки.',true);else if(result.error)toast('Не удалось проверить или изменить статус защиты.',true);else if(result.granted)toast(result.already?'Защита хранилища уже включена.':'Браузер разрешил защищённое хранение.');else toast('Браузер не включил защиту. Сохраняйте резервную копию JSON.',true)}
