function readSavedFilterViews(){try{const values=JSON.parse(preferences.get(SAVED_FILTER_VIEWS_KEY)||'[]');if(!Array.isArray(values))return [];return values.filter(value=>value&&typeof value.id==='string'&&typeof value.name==='string'&&value.name.trim()).slice(0,MAX_SAVED_FILTER_VIEWS).map(value=>({id:value.id.slice(0,80),name:value.name.trim().slice(0,40),filters:normalizeFilterSnapshot(value.filters)}))}catch{return []}}
