let toastTimer=0;
function toast(message,error=false,action=null){
  clearTimeout(toastTimer);
  const node=document.createElement('div');node.className=`toast${error?' toast-error':''}`;
  const text=document.createElement('span');text.className='toast-message';text.textContent=message;node.append(text);
  if(action){const button=document.createElement('button');button.type='button';button.className='toast-action';button.textContent=action.label;button.addEventListener('click',async()=>{clearTimeout(toastTimer);node.remove();try{await action.run()}catch(failure){toast(`Не удалось выполнить действие: ${failure.message}`,true)}});node.append(button)}
  $('#toast-region').replaceChildren(node);toastTimer=setTimeout(()=>{if(node.isConnected){node.remove();action?.onDismiss?.()}},action?7000:3300);
  return node;
}
