function filters(){return {query:$('#search-input')?.value||'',type:$('#filter-type')?.value||'Все типы',status:$('#filter-status')?.value||'Все статусы',tag:$('#filter-tag')?.value||'Все теги',sort:$('#sort-projects')?.value||'featured',featuredOnly:$('#filter-featured')?.checked||false,layout:projectLayout}}
function filterTagOptions(selected){const tags=[...new Set(model.projects.flatMap(project=>project.tags||[]))].sort((a,b)=>a.localeCompare(b,'ru')),missing=selected!=='Все теги'&&!tags.includes(selected);return `${missing?`<option selected>${esc(selected)}</option>`:''}${tags.map(tag=>`<option ${selected===tag?'selected':''}>${esc(tag)}</option>`).join('')}`}
function savedFilterToolbar(current){const views=readSavedFilterViews(),active=views.find(item=>sameFilterSnapshot(item.filters,current)),open=savedViewsExpanded??!matchMedia('(max-width: 600px)').matches;return `<details id="saved-views-disclosure" class="saved-views-disclosure" ${open?'open':''}><summary><span>Мои подборки</span><small>${active?`Выбрана: ${esc(active.name)}`:`${views.length}/${MAX_SAVED_FILTER_VIEWS} сохранено`}</small><span class="disclosure-chevron" aria-hidden="true"></span></summary><section class="saved-views" aria-label="Сохранённые представления"><div class="saved-views-copy"><b>Мои подборки</b><small>Фильтры, сортировка и вид · локально</small></div><label class="visually-hidden" for="saved-filter-view">Выбрать сохранённое представление</label><select id="saved-filter-view" aria-label="Сохранённые представления"><option value="">Выбрать представление…</option>${views.map(item=>`<option value="${esc(item.id)}" ${active?.id===item.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select><button type="button" class="button button-quiet" data-action="save-filter-view" title="Сохранить фильтры, сортировку и текущий вид" ${views.length>=MAX_SAVED_FILTER_VIEWS&&!active?'disabled':''}>Сохранить вид</button><button type="button" class="button button-quiet saved-view-delete" data-action="delete-filter-view" aria-label="Удалить выбранное представление" title="Удалить выбранную подборку" ${active?'':'disabled'}>Удалить</button><span class="saved-view-limit">${views.length}/${MAX_SAVED_FILTER_VIEWS}</span></section></details>`}
function bulkSelectionToolbar(rows){const selected=model.projects.filter(project=>selectedProjectIds.has(project.id)),visible=new Set(rows.map(project=>project.id)),outside=selected.filter(project=>!visible.has(project.id)).length;if(!selected.length)return '';const canFeature=selected.some(project=>!project.featured),canUnfeature=selected.some(project=>project.featured);return `<section class="bulk-toolbar" aria-label="Массовые действия с проектами"><div class="bulk-selection-count"><b>${countLabel(selected.length,['проект выбран','проекта выбрано','проектов выбрано'])}</b>${outside?`<small>${outside} вне текущего фильтра</small>`:'<small>Выбраны проекты в текущем списке</small>'}</div><div class="bulk-actions" role="group" aria-label="Действия над выбранными проектами">${canFeature?'<button type="button" class="button button-quiet" data-bulk="feature">В избранное</button>':''}${canUnfeature?'<button type="button" class="button button-quiet" data-bulk="unfeature">Убрать из избранного</button>':''}<button type="button" class="button button-danger-quiet" data-bulk="delete">Удалить</button><button type="button" class="text-button" data-bulk="clear">Снять выбор</button></div></section>`}
function announceSelection(){const count=selectedProjectIds.size;$('#search-announcer').textContent=count?`Выбрано ${countLabel(count,['проект','проекта','проектов'])}.`:'Выбор снят.'}
function setProjectSelection(id,selected){if(selected)selectedProjectIds.add(Number(id));else selectedProjectIds.delete(Number(id));render();announceSelection();document.querySelector(`[data-select-project="${Number(id)}"]`)?.focus({preventScroll:true})}
function selectVisibleProjects(checked){const visible=filterProjects(model.projects,filters());for(const project of visible){if(checked)selectedProjectIds.add(project.id);else selectedProjectIds.delete(project.id)}render();announceSelection();$('#select-visible-projects')?.focus({preventScroll:true})}
function clearProjectSelection(){selectedProjectIds.clear();render();announceSelection();$('#select-visible-projects')?.focus({preventScroll:true})}
async function setSelectedFeatured(featured){const selected=new Set(model.projects.filter(project=>selectedProjectIds.has(project.id)).map(project=>project.id));if(!selected.size)return;try{await save(next=>{next.projects=next.projects.map(project=>selected.has(project.id)?{...project,featured}:project);next.demo=false;return true});toast(featured?'Выбранные проекты добавлены в избранное.':'Выбранные проекты убраны из избранного.');document.querySelector(`[data-bulk="${featured?'unfeature':'feature'}"]`)?.focus({preventScroll:true})}catch(error){toast(`Не удалось обновить проекты: ${error.message}`,true)}}
function deleteSelectedProjects(){const ids=model.projects.filter(project=>selectedProjectIds.has(project.id)).map(project=>project.id);if(!ids.length)return;const label=countLabel(ids.length,['проект','проекта','проектов']);if(confirm(`Удалить ${label}? Их можно восстановить в течение 7 секунд.`))removeProjectsWithUndo(ids,`Удалено ${label}. Можно отменить в течение 7 секунд.`)}
function openSavedFilterDialog(){pendingFilterView=normalizeFilterSnapshot(filters());const existing=readSavedFilterViews().find(item=>sameFilterSnapshot(item.filters,pendingFilterView));$('#saved-filter-name').value=existing?.name||'';$('#saved-filter-form-error').textContent='';openDialog($('#saved-filter-dialog'),$('#saved-filter-name'),document.activeElement)}
function persistSavedFilterView(){const name=$('#saved-filter-name').value.trim(),error=$('#saved-filter-form-error');if(!name){error.textContent='Введите название подборки.';$('#saved-filter-name').focus();return}if(name.length>40){error.textContent='Название должно быть не длиннее 40 символов.';return}const views=readSavedFilterViews(),same=views.find(item=>sameFilterSnapshot(item.filters,pendingFilterView)),nameCollision=views.find(item=>item.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru')&&item.id!==same?.id);if(nameCollision){error.textContent=`Название «${nameCollision.name}» уже используется. Выберите другое.`;$('#saved-filter-name').focus();return}if(!same&&views.length>=MAX_SAVED_FILTER_VIEWS){error.textContent=`Можно сохранить не больше ${MAX_SAVED_FILTER_VIEWS} подборок.`;return}const next=same?views.map(item=>item.id===same.id?{...item,name,filters:pendingFilterView}:item):[...views,{id:globalThis.crypto?.randomUUID?.()||`view-${Date.now()}-${Math.random().toString(36).slice(2)}`,name,filters:pendingFilterView}];try{preferences.set(SAVED_FILTER_VIEWS_KEY,JSON.stringify(next))}catch(failure){error.textContent=`Не удалось сохранить: ${failure.message}`;return}const updated=Boolean(same);pendingFilterView=null;$('#saved-filter-dialog').close();render();$('#saved-filter-view')?.focus();toast(updated?'Подборка обновлена.':'Подборка сохранена на этом устройстве.')}
function applySavedFilterView(id){const saved=readSavedFilterViews().find(item=>item.id===id);if(!saved){render();return}const snapshot=saved.filters,tag=$('#filter-tag');for(const [selector,value] of [['#search-input',snapshot.query],['#filter-type',snapshot.type],['#filter-status',snapshot.status],['#sort-projects',snapshot.sort]])$(selector).value=value;$('#filter-featured').checked=snapshot.featuredOnly;if(tag){if(snapshot.tag!=='Все теги'&&![...tag.options].some(option=>option.value===snapshot.tag))tag.add(new Option(snapshot.tag,snapshot.tag));tag.value=snapshot.tag}projectLayout=snapshot.layout;preferences.set('folio-project-layout',projectLayout);view='projects';render();announceProjectResults();$('#saved-filter-view')?.focus();toast(`Подборка «${saved.name}» применена.`)}
function deleteSavedFilterView(){const id=$('#saved-filter-view')?.value,views=readSavedFilterViews(),index=views.findIndex(item=>item.id===id),removed=views[index];if(!removed)return;views.splice(index,1);try{preferences.set(SAVED_FILTER_VIEWS_KEY,JSON.stringify(views));render();$('#saved-filter-view')?.focus();toast(`Подборка «${removed.name}» удалена.`,false,{label:'Отменить',onDismiss:()=>requestAnimationFrame(()=>{if(document.activeElement===document.body||!document.activeElement?.isConnected)$('#saved-filter-view')?.focus({preventScroll:true})}),run:async()=>{const restored=readSavedFilterViews();if(restored.some(item=>item.id===removed.id))throw new Error('Такая подборка уже существует.');restored.splice(Math.min(index,restored.length),0,removed);preferences.set(SAVED_FILTER_VIEWS_KEY,JSON.stringify(restored));render();$('#saved-filter-view')?.focus();toast(`Подборка «${removed.name}» восстановлена.`)}})}catch(error){toast(`Не удалось удалить: ${error.message}`,true)}}
function projects(){const f=filters(),rows=filterProjects(model.projects,f),activeCount=[f.query.trim(),f.type!=='Все типы',f.status!=='Все статусы',f.tag!=='Все теги',f.featuredOnly,f.sort!=='featured'].filter(Boolean).length,filtersOpen=projectFiltersExpanded??!matchMedia('(max-width: 600px)').matches;return `${head('КАТАЛОГ РАБОТ','Все проекты','Ищите, сортируйте и управляйте своим портфолио.',`<button class="button button-accent" data-action="new-project">＋ Новый проект</button>`)}<section class="filter-panel"><label class="search-field"><span class="search-icon" aria-hidden="true"></span><input id="search-input" type="search" placeholder="Название, технология, тег, роль…" value="${esc(f.query)}" aria-label="Поиск проектов"><kbd>Ctrl/⌘ K</kbd></label><details id="project-filter-disclosure" class="project-filter-disclosure" ${filtersOpen?'open':''}><summary><span>Фильтры</span><small>${activeCount?`${activeCount} активно`:'Тип · статус · тег · порядок'}</small><span class="disclosure-chevron" aria-hidden="true"></span></summary><div class="filter-disclosure-body"><select id="filter-type" aria-label="Тип"><option>Все типы</option>${TYPES.map(x=>`<option ${f.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-status" aria-label="Статус"><option>Все статусы</option>${STATUSES.map(x=>`<option ${f.status===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-tag" aria-label="Тег"><option>Все теги</option>${filterTagOptions(f.tag)}</select><select id="sort-projects" aria-label="Сортировка проектов"><option value="featured" ${f.sort==='featured'?'selected':''}>Сначала избранные</option><option value="order" ${f.sort==='order'?'selected':''}>Мой порядок</option><option value="newest" ${f.sort==='newest'?'selected':''}>Новые</option><option value="oldest" ${f.sort==='oldest'?'selected':''}>Старые</option><option value="title" ${f.sort==='title'?'selected':''}>А → Я</option></select><label class="check-filter"><input id="filter-featured" type="checkbox" ${f.featuredOnly?'checked':''}> Только избранное</label></div></details></section>${savedFilterToolbar(f)}${bulkSelectionToolbar(rows)}<div class="results-line"><div class="result-summary"><b>${rows.length} ${plural(rows.length)}</b><span>${rows.length===model.projects.length?"Показаны все работы":"Фильтры применены"}</span></div><div class="results-actions"><label class="select-visible-control"><input id="select-visible-projects" type="checkbox" aria-label="Выбрать показанные проекты"><span>Выбрать показанные</span></label><div class="view-toggle" role="group" aria-label="Вид проектов"><button type="button" data-layout-choice="cards" aria-pressed="${projectLayout==="cards"?"true":"false"}">Карточки</button><button type="button" data-layout-choice="list" aria-pressed="${projectLayout==="list"?"true":"false"}">Список</button></div><button class="text-button" id="reset-filters" aria-label="Сбросить поиск, фильтры и сортировку" ${activeCount?'':'hidden'}>Сбросить фильтры</button></div></div>${rows.length?`<div class="project-grid${projectLayout==="list"?" project-list":""}">${rows.map(project=>card(project,true)).join("")}</div>`:`<div class="empty-state"><span>⌕</span><b>${model.projects.length?'Ничего не найдено':'Добавьте первый проект'}</b><p>${model.projects.length?'Измените запрос или сбросьте фильтры.':'Ваше портфолио начнётся с одной хорошей истории.'}</p><button class="button button-quiet" id="reset-empty">${model.projects.length?'Сбросить фильтры':'＋ Новый проект'}</button></div>`}`}
function showcase(){
  const featured=filterProjects(model.projects,{sort:'featured'}).filter(project=>project.featured);
  const developer=model.developer;
  const intro=developer.introduction?esc(developer.introduction).replaceAll('\n','<br>'):'Избранные кейсы из вашего локального портфолио.';
  const contacts=[[developer.include_email&&developer.email?`mailto:${developer.email}`:'','Email'],[developer.include_website&&developer.website_url?developer.website_url:'','Личный сайт'],[developer.include_github&&developer.github_url?developer.github_url:'','GitHub']]
    .filter(([href])=>href).map(([href,label])=>`<a href="${esc(href)}"${href.startsWith('mailto:')?'':' target="_blank" rel="noopener noreferrer"'}>${label} ↗</a>`).join('');
  const actions=`<button class="button button-quiet" data-action="export-md">Экспорт Markdown</button><button class="button button-quiet" data-action="preview-static">Предпросмотр HTML</button><button class="button button-accent" data-action="export-static">↓ Скачать готовую витрину</button>`;
  const themePicker=`<label class="showcase-theme-picker"><span>Стиль HTML-страницы</span><select id="showcase-theme" aria-describedby="showcase-theme-help"><option value="editorial" ${showcaseTheme==='editorial'?'selected':''}>Редакционный</option><option value="night" ${showcaseTheme==='night'?'selected':''}>Ночной</option><option value="gallery" ${showcaseTheme==='gallery'?'selected':''}>Галерея</option></select><small id="showcase-theme-help">Меняет только файл витрины, не карточки проектов.</small></label>`;
  const cards=featured.length?`<div class="project-grid showcase-grid">${featured.map(card).join('')}</div>`:'<div class="empty-state"><img class="empty-state-art" src="./assets/illustrations/featured-empty-folio.webp" alt="" aria-hidden="true"><b>Витрина пока не заполнена</b><p>Отметьте проект как избранный, чтобы показать его здесь.</p><button class="button button-quiet" data-view="projects">Выбрать проекты</button></div>';
  return `${head('ПРЕДПРОСМОТР ВИТРИНЫ','Работы, которыми<br>хочется поделиться.','Проверьте избранные кейсы и автономную страницу перед скачиванием.',actions)}${themePicker}<div class="showcase-banner"><span class="eyebrow">${esc(developer.specialization).toUpperCase()}</span><h2>${esc(developer.full_name)}</h2><p>${intro}</p>${contacts?`<nav class="profile-contact-links" aria-label="Контакты автора">${contacts}</nav>`:''}<span class="showcase-count">${esc(caseCountLabel(featured.length).toUpperCase())}</span></div>${cards}`;
}
function settings(){const d=model.developer;return `${head('ПРОСТРАНСТВО','Настройки и данные','Ваши проекты сохранены только в этом браузере.',`<span class="local-lock">Локально на этом устройстве</span>`)}<div class="settings-grid"><section class="settings-card"><span class="eyebrow">ПРОФИЛЬ</span><h2>Как вас представить?</h2><p>Добавьте короткое вступление и выберите контакты, которые попадут в предпросмотр и статический экспорт.</p><form id="profile-form" class="settings-form"><label class="field"><span>Имя</span><input name="full_name" required maxlength="90" value="${esc(d.full_name)}"></label><label class="field"><span>Специализация</span><input name="specialization" required maxlength="90" value="${esc(d.specialization)}"></label><label class="field"><span>Вступление</span><textarea name="introduction" maxlength="800" rows="4" placeholder="Коротко о вашем подходе и интересах">${esc(d.introduction)}</textarea><small class="field-hint">До 800 символов. Текст появится во вступлении витрины.</small></label><label class="field"><span>Email</span><input name="email" type="email" maxlength="254" autocomplete="email" value="${esc(d.email)}"></label><label class="profile-toggle"><input type="checkbox" name="include_email" ${d.include_email?'checked':''}><span>Показывать email в портфолио</span></label><label class="field"><span>Личный сайт</span><input name="website_url" type="url" inputmode="url" maxlength="300" placeholder="https://..." value="${esc(d.website_url)}"></label><label class="profile-toggle"><input type="checkbox" name="include_website" ${d.include_website?'checked':''}><span>Показывать личный сайт в портфолио</span></label><label class="field"><span>GitHub</span><input name="github_url" type="url" inputmode="url" maxlength="300" placeholder="https://github.com/..." value="${esc(d.github_url)}"></label><label class="profile-toggle"><input type="checkbox" name="include_github" ${d.include_github?'checked':''}><span>Показывать GitHub в портфолио</span></label><div class="profile-form-error" id="profile-form-error" role="alert" aria-live="polite"></div><button class="button button-dark">Сохранить профиль</button></form></section><section class="settings-card"><span class="eyebrow">РЕЗЕРВНАЯ КОПИЯ</span><h2>Ваши данные — под контролем</h2><p>JSON переносит проекты между настольной и браузерной версиями. Формат данных и основные ограничения у них общие.</p><ol class="transfer-steps"><li><b>Экспорт</b><span>На старом устройстве скачайте JSON-копию портфолио.</span></li><li><b>Передача файла</b><span>Перешлите его себе удобным способом или перенесите по кабелю.</span></li><li><b>Импорт</b><span>На новом устройстве откройте folio и выберите «Импортировать JSON».</span></li></ol><div class="data-actions"><button class="button button-accent" data-action="export-json">↓ Скачать резервную копию</button><button class="button button-quiet" data-action="import-json">↑ Импортировать JSON</button><button class="button button-quiet" data-action="export-csv">Экспорт CSV</button></div><div class="data-info"><b>Сохранение на устройстве</b><span>IndexedDB этого браузера. Для другого устройства экспортируйте JSON и импортируйте файл.</span></div><div class="storage-reliability" id="storage-reliability" data-storage-status="checking"><div class="storage-reliability-heading"><span class="storage-reliability-indicator" aria-hidden="true"></span><div><b id="storage-persistence-title">Проверяем хранилище…</b><span id="storage-persistence-description" role="status" aria-live="polite">Оцениваем место и статус защиты в этом браузере.</span></div></div><div class="storage-meter" id="storage-meter" role="progressbar" aria-label="Использование хранилища этого браузера" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-valuetext="Проверяем" hidden><span id="storage-meter-fill"></span></div><div class="storage-meter-caption"><span>Использовано</span><b id="storage-usage">Проверяем…</b></div><button class="button button-accent storage-protection-button" type="button" data-action="request-persistent-storage" disabled>Попросить защиту от автоочистки</button><small class="storage-reliability-note">В приватном режиме данные могут удалиться после закрытия сеанса. Для постоянного хранения используйте обычный профиль. Даже при защите браузера регулярно сохраняйте JSON-копию вне профиля.</small></div></section><section class="settings-card danger-card"><span class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</span><h2>Очистить рабочее пространство</h2><p>Все проекты будут удалены из этого браузера. Это действие нельзя отменить.</p><button class="button button-danger" data-action="clear-all">Удалить все проекты</button></section><section class="settings-card about-card"><span class="eyebrow">О ПРОЕКТЕ</span><h2>folio® <span class="version-chip">LOCAL · PWA</span></h2><p>Локальное портфолио с офлайн-доступом. Автоматической облачной синхронизации нет.</p><div class="offline-line"><i></i><span id="offline-text">${navigator.onLine?'Готово к работе без сети':'Офлайн — данные доступны'}</span></div><button class="text-button install-button" data-action="install" hidden>Установить приложение</button></section></div>`}
function render(){const filterDisclosure=$('#project-filter-disclosure'),viewsDisclosure=$('#saved-views-disclosure');if(filterDisclosure)projectFiltersExpanded=filterDisclosure.open;if(viewsDisclosure)savedViewsExpanded=viewsDisclosure.open;selectedProjectIds=new Set([...selectedProjectIds].filter(id=>model.projects.some(project=>project.id===id)));main.innerHTML=({dashboard,projects,showcase,settings})[view]();main.setAttribute('aria-busy','false');if(view==='settings')void refreshStorageStatus();$('#breadcrumb-current').textContent=({dashboard:'Обзор',projects:'Мои проекты',showcase:'Витрина',settings:'Настройки и данные'})[view];document.querySelectorAll('[data-view]').forEach(x=>{const current=x.dataset.view===view;x.classList.toggle('active',current);if(x.matches('.nav-item,.mobile-nav-item')){if(current)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')}});$('#theme-toggle').setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));$('#nav-count').textContent=model.projects.length;$('#avatar-small').textContent=(model.developer.full_name||'Д')[0].toLocaleUpperCase('ru');$('#profile-small-name').textContent=model.developer.full_name;$('#profile-small-role').textContent=model.developer.specialization;if(installPrompt&&$('.install-button'))$('.install-button').hidden=false;const selectVisible=$('#select-visible-projects');if(selectVisible){const visible=filterProjects(model.projects,filters()),selected=visible.filter(project=>selectedProjectIds.has(project.id)).length;selectVisible.checked=visible.length>0&&selected===visible.length;selectVisible.indeterminate=selected>0&&selected<visible.length;selectVisible.disabled=!visible.length}}
function updateCaseGuide(){const form=$('#project-form'),bar=$('#case-guide-progress');if(!form||!bar)return;const value=name=>String(form.elements.namedItem(name)?.value||'').trim(),items=caseStoryItems({context:value('context'),role:value('role'),solution:value('solution'),process:value('process'),outcome:value('outcome'),metrics:value('metrics'),cover_image_data:value('cover_image_data'),cover_image:editingCoverPath,gallery_images:editingGallery});const completed=items.filter(([, ,done])=>done).length,total=items.length;bar.setAttribute('aria-valuenow',String(completed));bar.setAttribute('aria-valuetext',`${completed} из ${total} дополнительных блоков`);bar.querySelector('.case-guide-progress-fill').style.width=`${completed/total*100}%`;$('#case-guide-count').textContent=`${completed} из ${total}`;const next=items.find(([, ,done])=>!done);$('#case-guide-next').textContent=next?completed===0?'Начните с задачи и своей роли. Заполняйте только то, что можете подтвердить.':`Следующий блок — «${next[1]}». Заполняйте его, если вам есть что показать.`:'Все подсказки учтены. Проверьте, что описание и изображения можно показывать.';for(const [key,,done] of items){const row=document.querySelector(`[data-case-guide="${key}"]`);if(row){row.dataset.complete=String(done);const marker=row.querySelector('span');if(marker)marker.textContent=done?'✓':'○'}}}
function renderCoverPreview(src=''){const host=$('#cover-preview');host.innerHTML=src?`<img src="${esc(src)}" alt="" style="object-position:${esc(editingCoverPosition)}" decoding="async">`:'<span>Добавьте иллюстрацию проекта</span>';$('#remove-cover').hidden=!src;const [x='50%',y='46%']=editingCoverPosition.split(' ');$('#cover-crop-x').value=parseInt(x,10);$('#cover-crop-y').value=parseInt(y,10);$('#cover-crop-value').value=`${x} · ${y}`;$('#cover-position').value=editingCoverPosition;updateCaseGuide()}
function renderGalleryEditor(){const host=$('#gallery-editor');if(!host)return;host.innerHTML=editingGallery.length?editingGallery.map((image,index)=>{const [x='50',y='50']=image.position.split(' ').map(value=>value.replace('%',''));return `<article class="gallery-item"><img src="${esc(image.image_data)}" alt="" aria-hidden="true" style="object-position:${esc(image.position)}"><div class="gallery-item-fields"><label>Описание изображения<input data-gallery-alt="${index}" aria-label="Описание дополнительного изображения ${index+1}" required maxlength="180" value="${esc(image.alt)}" placeholder="Опишите, что показано"></label><fieldset><legend>Кадрирование</legend><label>По горизонтали <input type="range" min="0" max="100" value="${x}" data-gallery-x="${index}" aria-label="Кадрирование по горизонтали, изображение ${index+1}"></label><label>По вертикали <input type="range" min="0" max="100" value="${y}" data-gallery-y="${index}" aria-label="Кадрирование по вертикали, изображение ${index+1}"></label></fieldset><div class="gallery-item-actions"><span>Деталь ${index+1} из ${GALLERY_MAX_IMAGES}</span><button type="button" class="text-button" data-gallery-up="${index}" aria-label="Переместить изображение ${index+1} выше" ${index?'':'disabled'}>↑</button><button type="button" class="text-button" data-gallery-down="${index}" aria-label="Переместить изображение ${index+1} ниже" ${index<editingGallery.length-1?'':'disabled'}>↓</button><button type="button" class="text-button" data-gallery-remove="${index}" aria-label="Удалить дополнительное изображение ${index+1}">Удалить</button></div></div></article>`}).join(''):'<p class="gallery-empty">Дополнительные изображения помогут показать экраны и детали проекта.</p>';$('#gallery-images-data').value=JSON.stringify(editingGallery);$('#gallery-files').disabled=editingGallery.length>=GALLERY_MAX_IMAGES;$('.gallery-file-label').setAttribute('aria-disabled',String(editingGallery.length>=GALLERY_MAX_IMAGES));updateCaseGuide()}
async function encodeGalleryImage(file,maxChars=GALLERY_MAX_IMAGE_DATA_CHARS){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Выберите PNG, JPEG или WebP.');if(file.size>10*1024*1024)throw new Error('Исходное изображение должно быть меньше 10 МиБ.');const source=URL.createObjectURL(file);try{const image=new Image();image.src=source;await image.decode();if(image.naturalWidth*image.naturalHeight>24000000)throw new Error('Уменьшите разрешение изображения до 24 мегапикселей.');const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d',{alpha:false}).drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.84,.76,.68,.6]){const data=canvas.toDataURL('image/webp',quality);if(data.length<=Math.min(GALLERY_MAX_IMAGE_DATA_CHARS,maxChars))return data}throw new Error('Сжатая картинка всё ещё слишком велика. Выберите изображение попроще.')}finally{URL.revokeObjectURL(source)}}
