function scheduleProjectDraftSave(){clearTimeout(draftSaveTimer);const status=$('#project-draft-status');if(status)status.textContent='Сохраняю черновик на этом устройстве…';draftSaveTimer=setTimeout(()=>{const form=$('#project-form'),draft={version:1,editing_id:editingId,cover_image:editingCoverPath,gallery_images:editingGallery,values:Object.fromEntries(new FormData(form)),featured:form.elements.featured.checked,updated_at:new Date().toISOString()};draftWriteQueue=draftWriteQueue.catch(()=>{}).then(()=>draftStore.put(draft)).then(()=>{const current=$('#project-draft-status');if(current)current.textContent='Черновик сохранён на этом устройстве.'}).catch(()=>{const current=$('#project-draft-status');if(current)current.textContent='Не удалось сохранить черновик. Оставьте форму открытой и попробуйте ещё раз.'})},350)}
async function openProject(p=null,restoreTarget=null){const requestedId=p?.id??null;let draft=null;try{draft=await draftStore.get()}catch{}if(draft){if(draft.editing_id===requestedId){if(!confirm('Найден несохранённый черновик этой карточки. Восстановить его?'))await clearProjectDraft();else if(!p)p={type:TYPES[0],status:'В разработке',created_at:today(),page_count:1,technologies:[],gallery_images:[]}}else{if(!confirm('Есть несохранённый черновик другой карточки. Удалить его и продолжить?'))return;await clearProjectDraft();draft=null}}editingId=requestedId;const form=$('#project-form');form.reset();$('#form-error').textContent='';$('#project-draft-status').textContent='Несохранённые изменения автоматически сохраняются на этом устройстве.';$('#project-dialog-title').textContent=p?'Редактировать проект':'Новый проект';p=p||{type:TYPES[0],status:'В разработке',created_at:today(),page_count:1,technologies:[],gallery_images:[]};editingCoverPath=draft?.cover_image||p.cover_image||'';editingCoverPosition=draft?.values?.cover_position||p.cover_position||'50% 46%';form.elements.cover_position.value=editingCoverPosition;editingGallery=(draft?.gallery_images||p.gallery_images||[]).map(image=>({...image}));form.elements.cover_image_data.value=p.cover_image_data||'';renderCoverPreview(p.cover_image_data||p.cover_image||'');renderGalleryEditor();for(const [key,val] of Object.entries({type:p.type,status:p.status,title:p.title||'',description:p.description||'',created_at:p.created_at,demo_url:p.demo_url||'',technologies:(p.technologies||[]).join(', '),role:p.role||'',outcome:p.outcome||'',context:p.context||'',solution:p.solution||'',process:p.process||'',metrics:p.metrics||'',tags:(p.tags||[]).join(', '),page_count:p.page_count||1,repository_url:p.repository_url||'',backend_stack:p.backend_stack||'',featured:p.featured||false})){const el=form.elements.namedItem(key);if(el){if(el.type==='checkbox')el.checked=!!val;else el.value=val}}if(draft){for(const [key,val] of Object.entries(draft.values||{})){const el=form.elements.namedItem(key);if(el){if(el.type==='checkbox')el.checked=key==='featured'?draft.featured:!!val;else el.value=val}}if(form.elements.featured)form.elements.featured.checked=!!draft.featured;editingCoverPosition=form.elements.cover_position.value||editingCoverPosition;editingGallery=(draft.gallery_images||[]).map(image=>({...image}));renderGalleryEditor();renderCoverPreview(form.elements.cover_image_data.value||editingCoverPath);$('#project-draft-status').textContent=`Черновик восстановлен · ${new Date(draft.updated_at).toLocaleString('ru-RU')}`}renderCaseTags();$('#case-tag-status').textContent='';$('#case-tag-entry').removeAttribute('aria-invalid');updateCaseGuide();toggleFields();setProjectFormStep(0,false);openDialog($('#project-dialog'),form.elements.title,restoreTarget||document.activeElement)}
const projectFormSteps=[{title:'Основа проекта',description:'Начните с названия и короткого описания. Остальное можно добавить позже.'},{title:'История кейса',description:'Расскажите о своей роли, решении и результате. Подсказки необязательны — указывайте только то, что можете подтвердить.'},{title:'Изображения и ссылки',description:'Добавьте обложку, материалы и ссылки, если они готовы. Можно сохранить проект и вернуться позже.'}];
