function renderImportPreview(fileName){const preview=previewPortfolioImport(model.projects,pendingImport.data.projects);$('#import-file-name').textContent=fileName;$('#import-summary').innerHTML=`В файле <b>${preview.incoming}</b> ${plural(preview.incoming)}, в портфолио сейчас <b>${preview.current}</b>. Совпадающих ID: <b>${preview.conflicts.length}</b>. Новых: <b>${preview.additions}</b>.<span class="replace-impact">Полная замена удалит текущие ${preview.current} ${plural(preview.current)}.</span>`;const list=$('#import-conflicts');if(preview.conflicts.length){list.innerHTML=`<h3>Совпадения по ID</h3><ul>${preview.conflicts.slice(0,8).map(item=>`<li><b>#${item.id}</b> ${esc(item.currentTitle)} <span aria-hidden="true">→</span> ${esc(item.incomingTitle)}</li>`).join('')}</ul>${preview.conflicts.length>8?`<small>И ещё ${preview.conflicts.length-8} совпадений.</small>`:''}`}else list.innerHTML='<p class="import-clean">Совпадающих ID нет. Все проекты можно добавить без замены существующих.</p>';$('#import-copy').hidden=!preview.conflicts.length;$('#import-keep').textContent=preview.conflicts.length?'Объединить, оставить мои совпадения':'Добавить в портфолио';$('#import-replace').textContent=preview.conflicts.length?'Заменить портфолио целиком':'Заменить портфолио целиком';openDialog($('#import-dialog'),$('#import-dialog [data-close-dialog]'),importDialogOpener||$('#import-file'));importDialogOpener=null}
async function applyPortfolioImport(strategy){
  if(!pendingImport)return;
  const incoming=pendingImport.data;
  let replacementBackup=null;
  if(strategy==='replace'&&model.projects.length){
    try{replacementBackup=serializePortfolioFile(model);await download('folio-before-import.json',replacementBackup,'application/json')}
    catch(error){toast(`Замена отменена: резервную копию не удалось сохранить (${error.message}).`,true);return}
  }
  try{
    if(replacementBackup){
      await portfolioWriteQueue.catch(()=>{});
      if(serializePortfolioFile(model)!==replacementBackup){toast('Замена отменена: портфолио изменилось до создания резервной копии. Повторите импорт.',true);return}
    }
    const result=await save(next=>{
      if(strategy==='replace'){
        next.title=incoming.title;next.developer=structuredClone(incoming.developer);next.projects=structuredClone(incoming.projects);next.demo=false;
        return{summary:`Импортировано проектов: ${next.projects.length}.`}
      }
      const merged=mergePortfolioImport(next.projects,incoming.projects,strategy);next.projects=merged.projects;next.demo=false;
      const{added,replaced,skipped,copied}=merged.stats;
      return{summary:`Импорт завершён: добавлено ${added}, обновлено ${replaced}, пропущено ${skipped}, копий ${copied}.`}
    });
    if(result===false)return;
    pendingImport=null;$('#import-dialog').close();
    toast(replacementBackup?`${result.summary} Резервная копия отправлена на скачивание до замены.`:result.summary)
  }catch(error){toast(`Импорт не сохранён: ${error.message}`,true)}
}
async function removeProjectsWithUndo(ids,message,{closeDetails=false}={}){
  const idSet=new Set(ids.map(Number)),wasDemo=model.demo,selectionBefore=new Set(selectedProjectIds);
  const removed=model.projects.map((project,index)=>({project:structuredClone(project),index})).filter(item=>idSet.has(item.project.id));
  if(!removed.length)return;
  try{const committed=await save(next=>{next.projects=next.projects.filter(project=>!idSet.has(project.id));next.demo=false;return true});if(!committed)return}
  catch(error){toast(`Проекты не удалены: ${error.message}`,true);return}
  for(const id of idSet)selectedProjectIds.delete(id);
  render();
  if(closeDetails&&$('#detail-dialog').open)$('#detail-dialog').close();
  const undoToast=toast(message,false,{
    label:'Отменить',
    onDismiss:()=>requestAnimationFrame(()=>{if(document.activeElement===document.body||!document.activeElement?.isConnected){const heading=$('#main-content h1')||main;heading.tabIndex=-1;heading.focus({preventScroll:true})}}),
    run:async()=>{
      const collision=removed.find(item=>model.projects.some(project=>project.id===item.project.id));
      if(collision)throw new Error('ID проекта уже занят. Данные не изменены.');
      try{await save(next=>{for(const item of [...removed].sort((a,b)=>a.index-b.index))next.projects.splice(Math.min(item.index,next.projects.length),0,item.project);next.demo=wasDemo;return true})}
      catch(error){throw new Error(`Не удалось восстановить проекты: ${error.message}`,{cause:error})}
      for(const item of removed){if(selectionBefore.has(item.project.id))selectedProjectIds.add(item.project.id)}
      render();
      $('#search-announcer').textContent=`Восстановлено проектов: ${removed.length}.`;
      const restored=removed.find(item=>document.querySelector(`[data-detail="${item.project.id}"]`));
      document.querySelector(`[data-detail="${restored?.project.id}"]`)?.focus();
      toast(removed.length===1?'Проект восстановлен.':`Восстановлено проектов: ${removed.length}.`);
    },
  });
  undoToast.querySelector('.toast-action')?.focus({preventScroll:true});
}

async function action(x){
  if(x==='request-persistent-storage'){await requestStorageProtection();return}
  if(x==='new-project'){openProject();return}
  if(x==='remove-cover'){editingCoverPath='';$('#cover-image-data').value='';$('#cover-file').value='';renderCoverPreview('');scheduleProjectDraftSave();return}
  if(x==='export-json'){try{await download('folio-backup.json',serializePortfolioFile(model),'application/json');toast(`Резервная копия ${window.Capacitor?.isNativePlatform?.()?'сохранена':'скачана'}`)}catch(error){toast(`Файл не сохранён: ${error.message}`,true)}return}
  const exports={
    'export-md':['portfolio.md',markdownExport(model),'text/markdown;charset=utf-8','Markdown-файл'],
    'export-csv':['projects.csv',csvExport(model),'text/csv;charset=utf-8','CSV-файл']
  };
  if(exports[x]){const [name,content,type,label]=exports[x];try{await download(name,content,type);toast(`${label} ${window.Capacitor?.isNativePlatform?.()?'сохранена':'скачан'}`)}catch(error){toast(`Файл не сохранён: ${error.message}`,true)}return}
  if(x==='preview-static'){previewStaticShowcase();return}
  if(x==='export-static'){exportStaticShowcase();return}
  if(x==='import-json'){importDialogOpener=document.activeElement;$('#import-file').click();return}
  if(x==='clear-all'||x==='clear-demo'){if(confirm(x==='clear-all'?'Удалить все проекты?':'Убрать демонстрационные проекты?'))removeProjectsWithUndo(model.projects.map(project=>project.id),'Проекты удалены.');return}
  if(x==='save-filter-view'){openSavedFilterDialog();return}
  if(x==='delete-filter-view'){deleteSavedFilterView();return}
  if(x==='install'&&installPrompt){installPrompt.prompt();installPrompt.userChoice.then(r=>{if(r.outcome==='accepted')toast('Приложение устанавливается');installPrompt=null;render()})}
}
